import { create_list_edit_delete_units } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    unitcreation: Boolean
  },
  data() {
    return {
      loading: false,
      unitName: ""
    };
  },
  watch: {
    unitcreation: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    async delete_mutation() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        var data = this.$store.getters.GetUserObj;
        try {
          let result = await API.graphql(graphqlOperation(create_list_edit_delete_units, {
            input: {
              material_unit_name: this.unitName,
              organization_id: data.organization.organization_id,
              action_type: "CREATE_UNIT"
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.create_list_edit_delete_units);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
            this.$refs.form.resetValidation();
            this.$refs.form.reset();
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.loading = false;
          this.$emit("errorMsg", error.errors[0].message);
        }
      }
    }
  }
};
